import android.app.Application
import dagger.hilt.android.HiltAndroidApp

@HiltAndroidApp
class MyApplication : Application() {
    // Hilt will generate code here.
    // You don't need to add anything specific for basic setup.
}


// A simple class you want to inject
// @Inject on the constructor tells Hilt how to create instances of this class
class AnalyticsHelper @Inject constructor() {
    fun logEvent(eventName: String) {
        // Log the event...
        println("Logging event: $eventName")
    }
}
