// Your MainActivity
import androidx.appcompat.app.AppCompatActivity
import android.os.Bundle
import dagger.hilt.android.AndroidEntryPoint
import javax.inject.Inject

// Annotate the Activity as an entry point
@AndroidEntryPoint
class MainActivity : AppCompatActivity() {

    // Use @Inject to request an instance of AnalyticsHelper
    // 'lateinit' is used because Hilt injects the field after the object is created
    @Inject
    lateinit var analyticsHelper: AnalyticsHelper

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        setContentView(R.layout.activity_main)

        // Now you can use the injected dependency
        analyticsHelper.logEvent("MainActivityCreated")
    }
}
